B.atk=new A.c7(B.UG,B.aam,!1)
B.a7N=new A.R("Don't sign it until you are at the counter.","\u0915\u093e\u0909\u0902\u091f\u0930 \u092a\u0930 \u092a\u0939\u0941\u0901\u091a\u0928\u0947 \u0924\u0915 \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0928 \u0915\u0930\u0947\u0902\u0964")
